    let dimension_linetype=optional_words(v.dimension_linetype);let dimension_extension_linetype1=optional_words(v.dimension_extension_linetype1);let dimension_extension_linetype2=optional_words(v.dimension_extension_linetype2);
    let interfere_object_visual_style=optional_words(v.interfere_object_visual_style);let interfere_viewport_visual_style=optional_words(v.interfere_viewport_visual_style);let drag_visual_style=optional_words(v.drag_visual_style);
