pub(super) fn reconstruct(reader:&mut Reader<'_,'_,'_>)->Result<DwgHeaderVariables,ValueError>{
    document(reader.one("dwg_header")?)?;
    let r=reader.one("dwg_header_units")?;document(r)?;
    let units=DwgHeaderUnits{unit1_conversion:real(r,2)?,unit2_conversion:real(r,3)?,unit3_conversion:real(r,4)?,unit4_conversion:real(r,5)?,unit1_name:r.text(6)?.into(),unit2_name:r.text(7)?.into(),unit3_name:r.text(8)?.into(),unit4_name:r.text(9)?.into()};
    let r=reader.one("dwg_header_modes")?;document(r)?;
    let modes=DwgHeaderModes{dimension_associative:boolean(r,2)?,dimension_show:boolean(r,3)?,polyline_generation:boolean(r,4)?,orthographic_mode:boolean(r,5)?,regeneration_mode:boolean(r,6)?,fill_mode:boolean(r,7)?,quick_text_mode:boolean(r,8)?,paper_space_linetype_scale:boolean(r,9)?,limits_check:boolean(r,10)?,user_timer:boolean(r,11)?,sketch_polyline:boolean(r,12)?,angle_direction:boolean(r,13)?,spline_frame:boolean(r,14)?,mirror_text:boolean(r,15)?,world_view:boolean(r,16)?,tile_mode:boolean(r,17)?,paper_limits_check:boolean(r,18)?,visual_retain:boolean(r,19)?,display_silhouette:boolean(r,20)?,polyline_ellipse:boolean(r,21)?};
    let r=reader.one("dwg_header_integer_settings")?;document(r)?;
    let integers=DwgHeaderIntegerSettings{proxy_graphics:word(r,2)?,tree_depth:signed_word(r,3)?,linear_units:word(r,4)?,linear_precision:word(r,5)?,angular_units:word(r,6)?,angular_precision:word(r,7)?,attribute_mode:word(r,8)?,point_display_mode:word(r,9)?,user_integer1:signed_word(r,10)?,user_integer2:signed_word(r,11)?,user_integer3:signed_word(r,12)?,user_integer4:signed_word(r,13)?,user_integer5:signed_word(r,14)?,spline_segments:word(r,15)?,surface_u:word(r,16)?,surface_v:word(r,17)?,surface_type:word(r,18)?,surface_tab1:word(r,19)?,surface_tab2:word(r,20)?,spline_type:word(r,21)?,shade_edge:word(r,22)?,shade_difference:word(r,23)?,unit_mode:word(r,24)?,maximum_active_viewports:word(r,25)?,isolines:word(r,26)?,multiline_justification:word(r,27)?,text_quality:word(r,28)?};
    let r=reader.one("dwg_header_scalars")?;document(r)?;
    let scalars=DwgHeaderScalars{linetype_scale:real(r,2)?,text_size:real(r,3)?,trace_width:real(r,4)?,sketch_increment:real(r,5)?,fillet_radius:real(r,6)?,thickness:real(r,7)?,angle_base:real(r,8)?,point_display_size:real(r,9)?,polyline_width:real(r,10)?,user_real1:real(r,11)?,user_real2:real(r,12)?,user_real3:real(r,13)?,user_real4:real(r,14)?,user_real5:real(r,15)?,chamfer_a:real(r,16)?,chamfer_b:real(r,17)?,chamfer_c:real(r,18)?,chamfer_d:real(r,19)?,facet_resolution:real(r,20)?,multiline_scale:real(r,21)?,current_entity_linetype_scale:real(r,22)?,current_entity_color_index:word(r,23)?,paper_space_viewport_scale:real(r,24)?};
    let r=reader.one("dwg_header_time")?;document(r)?;
    let time=DwgHeaderTimeState{created_at:DwgJulianDate{days:unsigned(r,2)?,milliseconds:unsigned(r,3)?},updated_at:DwgJulianDate{days:unsigned(r,4)?,milliseconds:unsigned(r,5)?},editing_duration:DwgJulianDate{days:unsigned(r,6)?,milliseconds:unsigned(r,7)?},user_timer_duration:DwgJulianDate{days:unsigned(r,8)?,milliseconds:unsigned(r,9)?}};
    let paper_space=reconstruct_space(reader,1,"paper")?;
    let model_space=reconstruct_space(reader,2,"model")?;
    let dimensions=reconstruct_dimensions(reader)?;
    let policy=reconstruct_policy(reader)?;
    let r=reader.one("dwg_header_strings")?;document(r)?;
    let strings=DwgHeaderStrings{menu:r.text(2)?.into(),dimension_postfix:r.text(3)?.into(),dimension_alternate_postfix:r.text(4)?.into(),dimension_alternate_measurement_zero_suffix:r.text(5)?.into(),dimension_measurement_zero_suffix:r.text(6)?.into(),hyperlink_base:r.text(7)?.into(),stylesheet:r.text(8)?.into(),fingerprint_guid:r.text(9)?.into(),version_guid:r.text(10)?.into(),project_name:r.text(11)?.into()};
    let relations=reconstruct_relations(reader)?;
    Ok(DwgHeaderVariables{units,modes,integers,scalars,time,paper_space,model_space,dimensions,policy,strings,relations})
}
fn reconstruct_coordinates(reader:&mut Reader<'_,'_,'_>,table:&'static str,owner:i64)->Result<Vec<f64>,ValueError>{reader.list(table,1,owner,2)?.into_iter().map(|row|real(row,3)).collect()}
fn reconstruct_space(reader:&mut Reader<'_,'_,'_>,id:i64,kind:&str)->Result<DwgHeaderSpaceGeometry,ValueError>{
    let r=reader.component("dwg_header_space",id)?;document(r)?;
    if r.text(2)?!=kind{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG header space has a mismatched kind"));}
    Ok(DwgHeaderSpaceGeometry{
        insertion_base:reconstruct_coordinates(reader,"dwg_header_space_insertion_base",id)?,extents_minimum:reconstruct_coordinates(reader,"dwg_header_space_extents_minimum",id)?,extents_maximum:reconstruct_coordinates(reader,"dwg_header_space_extents_maximum",id)?,limits_minimum:reconstruct_coordinates(reader,"dwg_header_space_limits_minimum",id)?,limits_maximum:reconstruct_coordinates(reader,"dwg_header_space_limits_maximum",id)?,elevation:real(r,3)?,
        ucs_origin:reconstruct_coordinates(reader,"dwg_header_space_ucs_origin",id)?,ucs_x_axis:reconstruct_coordinates(reader,"dwg_header_space_ucs_x_axis",id)?,ucs_y_axis:reconstruct_coordinates(reader,"dwg_header_space_ucs_y_axis",id)?,ucs_orthographic_view:word(r,4)?,
        ucs_origin_top:reconstruct_coordinates(reader,"dwg_header_space_ucs_origin_top",id)?,ucs_origin_bottom:reconstruct_coordinates(reader,"dwg_header_space_ucs_origin_bottom",id)?,ucs_origin_left:reconstruct_coordinates(reader,"dwg_header_space_ucs_origin_left",id)?,ucs_origin_right:reconstruct_coordinates(reader,"dwg_header_space_ucs_origin_right",id)?,ucs_origin_front:reconstruct_coordinates(reader,"dwg_header_space_ucs_origin_front",id)?,ucs_origin_back:reconstruct_coordinates(reader,"dwg_header_space_ucs_origin_back",id)?
    })
}
